import { useEffect, useState } from "react";
import api from "../api";

function Feed() {
  /* ================= STATE ================= */
  const [posts, setPosts] = useState([]);
  const [activePost, setActivePost] = useState(null);
  const [comments, setComments] = useState([]);
  const [commentText, setCommentText] = useState("");

  // UI-level like state (fast + demo-safe)
  const [likedPosts, setLikedPosts] = useState({});
  const [likeCounts, setLikeCounts] = useState({});
  const [commentCounts, setCommentCounts] = useState({});

  // TEMP (later from login)
  const userId = 1;

  /* ================= FETCH FEED ================= */
  useEffect(() => {
    fetchFeed();
  }, []);

  const fetchFeed = async () => {
    const res = await api.get("/feed");
    setPosts(res.data);
    res.data.forEach()

    // initialize counts (demo-safe)
    const likeMap = {};
    const commentMap = {};
    res.data.forEach(p => {
      likeMap[p.post_id] = 0;
      commentMap[p.post_id] = 0;
    });
    setLikeCounts(likeMap);
    setCommentCounts(commentMap);
  };

  /* ================= LIKE TOGGLE ================= */
  const toggleLike = async (postId) => {
    const isLiked = likedPosts[postId];

    if (isLiked) {
      await api.delete("/post/like", {
        data: { post_id: postId, user_id: userId }
      });
    } else {
      await api.post("/post/like", {
        post_id: postId,
        user_id: userId
      });
    }

    setLikedPosts(prev => ({
      ...prev,
      [postId]: !isLiked
    }));

    setLikeCounts(prev => ({
      ...prev,
      [postId]: isLiked ? prev[postId] - 1 : prev[postId] + 1
    }));
  };

  /* ================= COMMENTS ================= */
  const toggleComments = async (postId) => {
    if (activePost === postId) {
      setActivePost(null);
      return;
    }

    const res = await api.get(`/post/${postId}/comments`);
    setComments(res.data);
    setCommentCounts(prev => ({
      ...prev,
      [postId]: res.data.length
    }));
    setActivePost(postId);
  };

  const addComment = async () => {
    if (!commentText) return;

    await api.post("/post/comment", {
      post_id: activePost,
      user_id: userId,
      comment_text: commentText
    });

    setCommentText("");
    toggleComments(activePost);
  };

  return (
    <div className="feed-layout">
      {/* ===== SIDEBAR ===== */}
      <aside className="feed-sidebar glass">
        <h3>Feed</h3>
        <button className="sidebar-btn">All Posts</button>
        <button className="sidebar-btn">Images</button>
        <button className="sidebar-btn">Articles</button>
      </aside>

      {/* ===== MAIN FEED ===== */}
      <main className="feed-main">
        {posts.map(post => (
          <div key={post.post_id} className="post-card glass">
            <p className="post-text">{post.content}</p>

            {post.image_url && (
              <img
                src={`http://localhost:5000${post.image_url}`}
                alt="post"
                className="post-image"
              />
            )}

            {/* ===== ACTION BAR ===== */}
            <div className="post-actions">
              <div
                className={`icon-wrap ${likedPosts[post.post_id] ? "liked" : ""}`}
                onClick={() => toggleLike(post.post_id)}
              >
                {/* LIKE SVG */}
                <svg viewBox="0 0 24 24">
                  <path d="M12 21s-7.5-4.35-10-8.5C-0.5 7.5 3.5 3 7.5 5.5 10 7 12 9 12 9s2-2 4.5-3.5C20.5 3 24.5 7.5 22 12.5 19.5 16.65 12 21 12 21z"/>
                </svg>
                <span>{likeCounts[post.post_id]}</span>
              </div>

              <div
                className="icon-wrap"
                onClick={() => toggleComments(post.post_id)}
              >
                {/* COMMENT SVG */}
                <svg viewBox="0 0 24 24">
                  <path d="M21 6h-18v10h4v4l4-4h10z"/>
                </svg>
                <span>{commentCounts[post.post_id]}</span>
              </div>
            </div>

            {/* ===== COMMENTS ===== */}
            {activePost === post.post_id && (
              <div className="comment-box">
                {comments.map((c, i) => (
                  <p key={i}>
                    <strong>{c.email}</strong>: {c.comment_text}
                  </p>
                ))}

                <input
                  placeholder="Write a comment..."
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                />
                <button onClick={addComment}>Post</button>
              </div>
            )}
          </div>
        ))}
      </main>
    </div>
  );
}

export default Feed;
